var loggingCallbacks={};function registerLoggingCallbacks(obj){var i,l,key,callbackNames=["begin","done","log","testStart","testDone","moduleStart","moduleDone"];function registerLoggingCallback(key){var loggingCallback=function(callback){if(objectType(callback)!=="function"){throw new Error("QUnit logging methods require a callback function as their first parameters.")}config.callbacks[key].push(callback)};loggingCallbacks[key]=loggingCallback;return loggingCallback}for(i=0,l=callbackNames.length;i<l;i++){key=callbackNames[i];if(objectType(config.callbacks[key])==="undefined"){config.callbacks[key]=[]}obj[key]=registerLoggingCallback(key)}}function runLoggingCallbacks(key,args){var i,l,callbacks;callbacks=config.callbacks[key];for(i=0,l=callbacks.length;i<l;i++){callbacks[i](args)}}function verifyLoggingCallbacks(){var loggingCallback,userCallback;for(loggingCallback in loggingCallbacks){if(QUnit[loggingCallback]!==loggingCallbacks[loggingCallback]){userCallback=QUnit[loggingCallback];QUnit[loggingCallback]=loggingCallbacks[loggingCallback];QUnit[loggingCallback](userCallback);if(global.console&&global.console.warn){global.console.warn("QUnit."+loggingCallback+" was replaced with a new value.\n"+"Please, check out the documentation on how to apply logging callbacks.\n"+"Reference: https://api.qunitjs.com/category/callbacks/")}}}}